cat > programs/task-380fcea9.py <<'PY'
def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = []
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 1:
                # The 1-ray bends: two cells east, then one north to its tip.
                cells = [(r, c, 1), (r, c + 1, 5), (r, c + 2, 5), (r - 1, c + 2, 1)]
                rays.append(cells)
            elif v == 2:
                rays.append([(r, c - d, 2 if d in (0, 4) else 5) for d in range(5)])
            elif v == 3:
                rays.append([(r + d, c, 3 if d in (0, 3) else 5) for d in range(4)])
            elif v == 6:
                rays.append([(r - d, c, 6 if d in (0, 6) else 5) for d in range(7)])
    # Collect in-bounds ray marks. Any overlap between distinct rays is a 4.
    owners = {}
    for i, ray in enumerate(rays):
        for r, c, color in ray:
            if 0 <= r < h and 0 <= c < w:
                owners.setdefault((r, c), []).append((i, color))
    collisions = []
    for (r, c), marks in owners.items():
        if len({i for i, _ in marks}) > 1:
            out[r][c] = 4
            collisions.append((r, c))
        else:
            out[r][c] = marks[-1][1]
    # A collision launches a down-left diagonal of 4s to the grid edge.
    for r, c in collisions:
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
